<?php require __DIR__.'/../config.php';require_admin();$allowed=['Pending','Confirmed','Packed','Shipped','Delivered','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){$status=$_POST['status']??'';$id=(int)($_POST['id']??0);if(in_array($status,$allowed,true)){$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Order status updated.');}go('/MediHome/admin/orders.php');}$orders=$pdo->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();$title='Manage Orders | MediHome';require __DIR__.'/../includes/header.php';?><div class="pagehead"><h1>Manage orders</h1><p>Update order status for the customer demo.</p></div><div class="adminnav"><a href="/MediHome/admin/index.php">Dashboard</a><a href="/MediHome/admin/medicines.php">Medicines</a><a href="/MediHome/admin/orders.php">Orders</a><a href="/MediHome/admin/logout.php">Logout</a></div><?php if(!$orders):?><div class="empty"><h2>No orders yet</h2></div><?php else:?><div class="tablewrap"><table class="table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?> <small><?=e($o['created_at'])?></small></td><td><?=e($o['customer_name'])?><br><?=e($o['email'])?><br><?=e($o['address'])?></td><td><?=money($o['total'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach($allowed as $s):?><option <?=$o['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn">Save</button></form></td></tr><?php endforeach;?></table></div><?php endif;?><?php require __DIR__.'/../includes/footer.php';?>